#!/usr/bin/env bash
# The image payload exceeds Linux MAX_ARG_STRLEN (128KB), so curl cannot
# take it as a command-line argument. Write the body to a temp file instead.
set -euo pipefail

# Load NVIDIA_API_KEY from deploy/.env
ENV_FILE="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)/deploy/.env"
set -a
source "$ENV_FILE"
set +a
: "${NVIDIA_API_KEY:?NVIDIA_API_KEY is not set in $ENV_FILE}"

payload_file=$(mktemp)
trap 'rm -f "$payload_file"' EXIT

cat > "$payload_file" << 'JSON'
{
	"model": "nvidia/nemotron-3-nano-omni-30b-a3b-reasoning",
	"messages": [
		{
			"role": "user",
			"content": [
				{
					"type": "text",
					"text": "\nExtract all transactions in this document in this format: \nTransaction Date|Transaction Description|User ID|Debit|Kredit|Balance\n\nExample:\n01/01/23 06:58:30 | FROM M013301051855500 TO013301074067500MP | 9844256 | 0.00 | 14,900,000.00 | 36,078,572.40\n"
				},
				{
					"type": "image_url",
					"image_url": {
						"url": "data:image/jpeg;base64,"
					}
				}
			]
		}
	]
}
JSON

curl --request POST \
  --url https://integrate.api.nvidia.com/v1/chat/completions \
  --header "Authorization: Bearer ${NVIDIA_API_KEY}" \
  --header 'Content-Type: application/json' \
  --data "@${payload_file}"
